import * as THREE from 'three/webgpu';
import * as TSL from 'three/tsl';
import { gsap } from 'gsap';
import { createMSDFTextMesh } from '@/text';

interface NodeConfig {
  textContent?: Record<string, string>;
  scenePosition?: { x: number; y: number; z: number };
  cinematicPrimitives?: any[];
}

interface NodeContext {
  textureLoader: THREE.TextureLoader;
  glbLoader: any;
  fontAtlas: (opts: any) => THREE.Object3D;
  primitives: Record<string, (obj: THREE.Object3D, params: any) => void>;
}

export default function createNode(config: NodeConfig, ctx: NodeContext): THREE.Object3D {
  const group = new THREE.Group();
  const timelines: gsap.core.Timeline[] = [];
  const toDispose: Array<{ dispose: () => void }> = [];

  const PANEL_W = 3.4;
  const PANEL_H = 1.9;
  const CORNER_RADIUS = 0.06;
  const TEXT_Z = 0.03;
  const BORDER_WIDTH = 0.006;

  // Panel plane geometry with rounded corners
  const planeGeo = new THREE.PlaneGeometry(PANEL_W, PANEL_H, 64, 64);
  const posArray = planeGeo.attributes.position.array as Float32Array;
  const halfW = PANEL_W / 2;
  const halfH = PANEL_H / 2;

  for (let i = 0; i < posArray.length; i += 3) {
    const x = posArray[i];
    const y = posArray[i + 1];
    const absX = Math.abs(x);
    const absY = Math.abs(y);

    if (absX > halfW - CORNER_RADIUS && absY > halfH - CORNER_RADIUS) {
      const dx = absX - (halfW - CORNER_RADIUS);
      const dy = absY - (halfH - CORNER_RADIUS);
      const dist = Math.hypot(dx, dy);
      if (dist > CORNER_RADIUS) {
        const scale = CORNER_RADIUS / dist;
        posArray[i] = x * scale;
        posArray[i + 1] = y * scale;
      }
    }
  }
  planeGeo.attributes.position.needsUpdate = true;
  toDispose.push(planeGeo);

  // Gradient material: #1a1a22 (top) → #111116 (bottom)
  const uv = TSL.uv();
  const colorTop = TSL.vec3(0.1019, 0.1019, 0.1333);
  const colorBot = TSL.vec3(0.0667, 0.0667, 0.0863);
  const colorNode = TSL.mix(colorTop, colorBot, uv.y);

  const planeMat = new THREE.MeshStandardNodeMaterial({
    colorNode,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
    side: THREE.FrontSide,
  });
  toDispose.push(planeMat);

  const plane = new THREE.Mesh(planeGeo, planeMat);
  plane.position.z = 0;
  group.add(plane);

  // Text: quotation mark (0.62 units tall, extruded, #ff2a38)
  let quoteMarkMesh: THREE.Object3D | null = null;
  try {
    quoteMarkMesh = ctx.fontAtlas({
      text: '"',
      fontSize: 0.62,
      font: 'Lora',
      fontWeight: 600,
      color: 0xff2a38,
      extrude: { depth: 0.04 },
      roughness: 0.5,
      metalness: 0.3,
    });
    quoteMarkMesh.position.set(-1.4, 0.7, TEXT_Z + 0.01);
    quoteMarkMesh.scale.set(1.04, 1.04, 1);
    group.add(quoteMarkMesh);
  } catch {
    // Fallback if fontAtlas unavailable
  }

  // Text: quote (Lora 20px, #e8ecf2, max-width 2.4)
  try {
    const quoteMesh = ctx.fontAtlas({
      text: 'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
      fontSize: 0.2,
      font: 'Lora',
      fontWeight: 400,
      color: 0xe8ecf2,
      lineHeight: 1.45,
      maxWidth: 2.4,
    });
    quoteMesh.position.set(-1.4, 0.25, TEXT_Z);
    group.add(quoteMesh);
  } catch {
    // Fallback
  }

  // Text: attribution (JetBrains Mono 13px, #e8ecf2, letter-spacing 0.08)
  try {
    const attrMesh = ctx.fontAtlas({
      text: 'M. OKAFOR',
      fontSize: 0.13,
      font: 'JetBrains Mono',
      fontWeight: 700,
      color: 0xe8ecf2,
      letterSpacing: 0.08,
    });
    attrMesh.position.set(-1.2, -0.4, TEXT_Z);
    group.add(attrMesh);
  } catch {
    // Fallback
  }

  // Text: caption (JetBrains Mono 9px, slightly dimmed)
  try {
    const capMesh = ctx.fontAtlas({
      text: 'COLLECTOR SINCE 2019',
      fontSize: 0.09,
      font: 'JetBrains Mono',
      fontWeight: 400,
      color: 0x8a8a8a,
      letterSpacing: 0.12,
    });
    capMesh.position.set(-1.2, -0.55, TEXT_Z);
    group.add(capMesh);
  } catch {
    // Fallback
  }

  // Accent rule: 0.2w × 0.02h, emissive #ff2a38 (intensity 1.4)
  const ruleGeo = new THREE.PlaneGeometry(0.2, 0.02);
  const ruleColor = TSL.vec3(1.0, 0.1647, 0.2235);
  const ruleMat = new THREE.MeshBasicNodeMaterial({
    colorNode: ruleColor,
    emissiveNode: ruleColor,
    emissiveIntensity: 1.4,
  });
  toDispose.push(ruleGeo);
  toDispose.push(ruleMat);

  const accentRule = new THREE.Mesh(ruleGeo, ruleMat);
  accentRule.position.set(-1.4, -0.25, TEXT_Z);
  group.add(accentRule);

  // ANIMATION 1: Panel fade-up (opacity 0→1, y +0.2→0, 500ms, cubic-bezier(0.25,0.46,0.45,0.94))
  const panelTimeline = gsap.timeline();
  planeMat.transparent = true;
  (planeMat as any).opacity = 0;
  panelTimeline.from(planeMat as any, {
    opacity: 0,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
  }, 0);
  panelTimeline.from(
    plane.position,
    {
      y: 0.2,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    },
    0
  );
  timelines.push(panelTimeline);

  // ANIMATION 2: Quote mark weighted-settle (scale 1.04→1.0, 900ms, delay 500ms, cubic-bezier(0.165,0.84,0.44,1))
  if (quoteMarkMesh) {
    const markTimeline = gsap.timeline({ delay: 0.5 });
    markTimeline.to(
      quoteMarkMesh.scale,
      {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
      },
      0
    );
    timelines.push(markTimeline);
  }

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    toDispose.forEach((res) => {
      if (res && typeof res.dispose === 'function') {
        res.dispose();
      }
    });
    group.traverse((child: any) => {
      if (child.geometry && typeof child.geometry.dispose === 'function') {
        child.geometry.dispose();
      }
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m: any) => {
            if (typeof m.dispose === 'function') m.dispose();
          });
        } else if (typeof child.material.dispose === 'function') {
          child.material.dispose();
        }
      }
    });
  };

  group.userData.handlers = {};

  return group;
}
